export const VEHICLE_BRANDS = Object.keys(VEHICLE_DATABASE).sort();

export const CAR_BRANDS = VEHICLE_BRANDS;

export function getModelsForBrand(brand: string): string[] {
  return (VEHICLE_DATABASE[brand]?.models ?? []).map(m => m.model);
}

export function getMarketValue(brand: string, model: string): number | null {
  const entry = VEHICLE_DATABASE[brand];
  if (!entry) return null;
  const m = entry.models.find(m => m.model === model);
  return m ? m.marketValueRp : null;
}

export function getMarketValueForYear(brand: string, model: string, year: number): number | null {
  const entry = VEHICLE_DATABASE[brand];
  if (!entry) return null;
  const m = entry.models.find(m => m.model === model);
  if (!m) return null;
  const yearStr = String(year);
  if (m.yearPrices?.[yearStr]) {
    return Math.round(m.yearPrices[yearStr]! * (1 - entry.discount) * 1_000_000);
  }
  const ageFactor = Math.max(0.35, 1 - (m.refYear - year) * 0.07);
  return Math.round(m.marketValueRp * ageFactor);
}

